236	    /**
237	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
238	     * already reached this many owners is rejected as a conflict.
239	     */
240	    static final int MAX_OWNERS_PER_CITY = 50;
241	
242	    @Override
243	    @Transactional
244	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
245	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
246	            throw new DuplicateTelephoneException(owner.getTelephone());
247	        }
248	        List<Owner> householdMembers = findHouseholdMembers(owner);
249	        if (!householdMembers.isEmpty() && !sharesHousehold) {
250	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
251	        }
252	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
253	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
254	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
255	        }
256	        owner.setNamesakeCount(countNamesakes(owner));
257	        if (owner.getRegistrationDate() == null) {
258	            owner.setRegistrationDate(LocalDate.now());
259	        }
260	        owner.setCustomerCode(CustomerCodeGenerator.format(
261	            owner.getCity(), owner.getLastName(), ownersInCity + 1));
262	        if (!householdMembers.isEmpty()) {
263	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
264	        }
265	        ownerRepository.save(owner);
266	        return owner.getHouseholdId();
267	    }
268	
269	    /**
270	     * Assign the stable household identifier to the new owner and to every existing member of the
271	     * household, persisting the members whose identifier changes, and return the shared identifier.
272	     */
273	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
274	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
275	        for (Owner member : householdMembers) {
276	            if (!householdId.equals(member.getHouseholdId())) {
277	                member.setHouseholdId(householdId);
278	                ownerRepository.save(member);
279	            }
280	        }
281	        return householdId;
282	    }
